"""Uncertainty budget for one KX-100 reading (first-order GUM), from MANUAL.md sections 5 and 7."""

import math

_F_MIN_HZ = 10e6
_F_MAX_HZ = 18e9
_F_BAND_EDGE_HZ = 8e9  # 10 MHz to 8 GHz inclusive / above 8 GHz to 18 GHz

_RANGE_LIMITS_DBM = {
    # LOW over-ranges above -10 dBm (reading invalid, error 201).
    "LOW": (-60.0, -10.0),
    # HIGH: specified -30 to +20 dBm; below -30 dBm the zero offset dominates, which the
    # budget reflects, but nothing below the instrument limit of -60 dBm can be measured.
    "HIGH": (-60.0, 20.0),
}

_ZERO_OFFSET_W = {"LOW": 0.5e-9, "HIGH": 50e-9}

_SQRT2 = math.sqrt(2.0)
_SQRT3 = math.sqrt(3.0)


def _is_real_number(x) -> bool:
    return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(x)


def combined_uncertainty_pct(
    reading_dbm: float, freq_hz: float, averages: int, power_range: str, gamma_source: float
) -> float:
    """Combined standard uncertainty u_c of one reading, in % of reading.

    reading_dbm: the reading; freq_hz: the signal frequency; averages: the averaging count N;
    power_range: "LOW" or "HIGH"; gamma_source: the source's reflection coefficient magnitude.

    Raises ValueError for inputs outside the instrument's specifications.
    """
    # --- validation -------------------------------------------------------------------------
    if not isinstance(power_range, str) or power_range.strip().upper() not in _RANGE_LIMITS_DBM:
        raise ValueError(f"power_range must be 'LOW' or 'HIGH', got {power_range!r}")
    rng = power_range.strip().upper()

    if not _is_real_number(reading_dbm):
        raise ValueError(f"reading_dbm must be a finite number, got {reading_dbm!r}")
    lo, hi = _RANGE_LIMITS_DBM[rng]
    if not (lo <= reading_dbm <= hi):
        raise ValueError(
            f"reading {reading_dbm} dBm is outside the {rng} range limits ({lo} to {hi} dBm)"
        )

    if not _is_real_number(freq_hz):
        raise ValueError(f"freq_hz must be a finite number, got {freq_hz!r}")
    if not (_F_MIN_HZ <= freq_hz <= _F_MAX_HZ):
        raise ValueError(f"frequency {freq_hz} Hz is outside 10 MHz to 18 GHz")

    if isinstance(averages, bool) or not isinstance(averages, int):
        if isinstance(averages, float) and averages.is_integer():
            averages = int(averages)
        else:
            raise ValueError(f"averages must be an integer, got {averages!r}")
    if not (1 <= averages <= 1024):
        raise ValueError(f"averages must be 1 to 1024, got {averages}")

    if not _is_real_number(gamma_source) or not (0.0 <= gamma_source <= 1.0):
        raise ValueError(f"gamma_source must be in [0, 1], got {gamma_source!r}")

    # --- contributions (standard uncertainties, % of reading) -------------------------------
    high_band = freq_hz > _F_BAND_EDGE_HZ
    p_w = 10.0 ** (reading_dbm / 10.0) / 1000.0

    u_accuracy = 0.50 / _SQRT3
    u_linearity = 0.30 / _SQRT3
    u_zero = (100.0 * _ZERO_OFFSET_W[rng] / p_w) / _SQRT3
    u_cal = (2.2 if high_band else 1.6) / 2.0
    u_noise = 2.0 / math.sqrt(averages)
    gamma_m = 0.15 if high_band else 0.10
    u_mismatch = (200.0 * gamma_source * gamma_m) / _SQRT2
    u_resolution = ((10.0 ** (0.005 / 10.0) - 1.0) * 100.0) / _SQRT3

    terms = (u_accuracy, u_linearity, u_zero, u_cal, u_noise, u_mismatch, u_resolution)
    return float(math.sqrt(sum(t * t for t in terms)))

